// What this does not prove:
// - the records are generated by this test, so it shows volume and handling and nothing about any real source.
import {test,expect} from 'bun:test';
import {mkdtempSync,mkdirSync,rmSync,writeFileSync,readFileSync,appendFileSync,statSync} from 'node:fs';
import {tmpdir} from 'node:os';
import {join,resolve,dirname} from 'node:path';
import {fileURLToPath} from 'node:url';
import {spawnSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {losslessJSON,videoRecord,windows,queryContract,openCollection,enqueue,claim,acceptPage,collect,importExport,deliver,status} from '../tools/traktok_collect.mjs';
const root=resolve(dirname(fileURLToPath(import.meta.url)),'../../..'),frontier=join(root,'cmd/BonfyreSourceFrontier/bonfyre-source-frontier');
const query={or:[{operation:'IN',field_name:'hashtag_name',field_values:['recipes','mealprep']}]};
function command(bin,args){const r=spawnSync(bin,args,{encoding:'utf8',timeout:120000,maxBuffer:1048576});expect(r.status).toBe(0);return r.stdout;}
async function fixture(fn){const dir=mkdtempSync(join(tmpdir(),'bf-traktok-test-')),path=join(dir,'frontier.db'),bodies=join(dir,'foreign');let db;
 try{command(frontier,['init','--db',path]);db=openCollection(path);await fn({dir,path,bodies,db});}finally{db?.close();rmSync(dir,{recursive:true,force:true})}}
const video=i=>({id:String(7302470379501604128n+BigInt(i)),username:'fixture_creator_'+i%1000,video_description:'Food café 🥣 '+i,hashtag_names:['recipe'],music_id:'7000000000000000001'});
const page=(videos,cursor,more)=>JSON.stringify({error:{code:'ok'},data:{videos,cursor,has_more:more,search_id:'search-fixture'}});
test('64-bit IDs survive numeric platform JSON and TraktoK renamed exports',()=>{
 const r=losslessJSON('{"id":7302470379501604128,"username":"food","caption":"7302470379501604128","n":3}');
 expect(r.id).toBe('7302470379501604128');expect(r.caption).toBe(r.id);expect(r.n).toBe(3);
 expect(videoRecord({video_id:r.id,author_name:'food'}).url).toEndWith('/@food/video/7302470379501604128');
 expect(()=>videoRecord({id:7302470379501604128,username:'food'})).toThrow('rounded');
 expect(()=>videoRecord({id:'1',username:'../../private'})).toThrow();
});
test('date sharding preserves every day, leap days and boolean query meaning',()=>{
 expect(windows('20240201','20240302')).toEqual([{start:'20240201',end:'20240301'},{start:'20240302',end:'20240302'}]);
 expect(()=>windows('20240230','20240301')).toThrow();expect(queryContract(query)).toEqual(query);expect(()=>queryContract({})).toThrow();
});
test('short pages continue, restart keeps cursor and search ID, and delivery uses native owner',()=>fixture(async({db,path,bodies,dir})=>{
 const {collection}=enqueue(db,query,'20260901','20260902');let calls=0;
 const first=await collect(db,{collection,bodyDir:bodies,token:'test-only',intervalMs:0,maxPages:1,transport:async()=>{calls++;return new Response(page([video(1)],100,true));}});
 expect(first.rows).toBe(1);expect(first.pages).toBe(1);
 const second=await collect(db,{collection,bodyDir:bodies,token:'test-only',intervalMs:0,maxPages:2,transport:async(u,opt)=>{const b=JSON.parse(opt.body);expect(b.cursor).toBe(100);expect(b.search_id).toBe('search-fixture');calls++;return new Response(page([video(2)],200,false));}});
 expect(second.pages).toBe(1);expect(calls).toBe(2);expect(status(db).unique_videos).toBe(2);expect(status(db).relations).toBe(6);
 const r=deliver(db,{dbPath:path,frontier,dir:join(dir,'out')});expect(r.delivered).toBe(2);expect(r.pending).toBe(0);
 expect(db.query("SELECT count(*) n FROM channel WHERE material='video_metadata' AND state='shadow'").get().n).toBe(2);
 expect(deliver(db,{dbPath:path,frontier,dir:join(dir,'out')}).delivered).toBe(0);
 for(const p of db.query('SELECT * FROM traktok_page').all())expect(createHash('sha256').update(readFileSync(p.body_path)).digest('hex')).toBe(p.digest);
}));
test('stale leases, repeated cursors and malformed pages never advance collection',()=>fixture(async({db,bodies})=>{
 const {collection}=enqueue(db,query,'20260901','20260902'),a=claim(db,collection,1000),b=claim(db,collection,122000);
 expect(()=>acceptPage(db,a,page([video(1)],100,true),bodies)).toThrow('stale');
 expect(()=>acceptPage(db,b,page([video(1)],0,true),bodies)).toThrow('non-progressing');expect(status(db).observations).toBe(0);
 acceptPage(db,b,page([video(1)],100,true),bodies);expect(status(db).observations).toBe(1);
}));
test('missing access, HTTP 429 and daily budget preserve resumability without false success',()=>fixture(async({db,bodies})=>{
 const {collection}=enqueue(db,query,'20260901','20260902');let calls=0;
 const none=await collect(db,{collection,bodyDir:bodies,token:'',transport:async()=>{calls++;throw Error('must not call')}});expect(none.state).toBe('credentials_required');expect(calls).toBe(0);
 const limited=await collect(db,{collection,bodyDir:bodies,token:'test-only',intervalMs:0,now:()=>100000,transport:async()=>new Response('',{status:429,headers:{'Retry-After':'120'}})});
 expect(limited.state).toBe('http_retry_deferred');expect(db.query('SELECT retry_at FROM traktok_shard').get().retry_at).toBe(220000);expect(status(db).pages).toBe(0);
 db.exec("UPDATE traktok_shard SET retry_at=0");
 const budget=await collect(db,{collection,bodyDir:bodies,token:'test-only',intervalMs:0,dailyBudget:1,now:()=>100000,transport:async()=>{throw Error('must not spend again')}});expect(budget.state).toBe('daily_request_budget');expect(budget.remote_requests).toBe(0);
}));
test('unauthorized API access is blocked and no body is promoted',()=>fixture(async({db,bodies})=>{
 const {collection}=enqueue(db,query,'20260901','20260902');const result=await collect(db,{collection,bodyDir:bodies,token:'test-only',intervalMs:0,transport:async()=>new Response('',{status:403})});
 expect(result.state).toBe('access_refused');expect(status(db).shards).toEqual([{state:'blocked',n:1}]);expect(status(db).unique_videos).toBe(0);
}));
test('TraktoK export resumes a bounded prefix and cannot round its identities',()=>fixture(async({db,bodies,dir})=>{
 const p=join(dir,'upstream.jsonl');writeFileSync(p,Array.from({length:7},(_,i)=>{const v=video(i);return JSON.stringify({...v,video_id:v.id,author_name:v.username,id:undefined,username:undefined})}).join('\n'));
 const a=await importExport(db,{path:p,bodyDir:bodies,sourceURI:'fixture:traktok-export',batchSize:2,maxRows:3});expect(a.rows).toBe(3);expect(a.state).toBe('row_budget_yield');
 const b=await importExport(db,{path:p,bodyDir:bodies,sourceURI:'fixture:traktok-export',batchSize:2,maxRows:10});expect(b.rows).toBe(4);expect(status(db).unique_videos).toBe(7);
 expect((await importExport(db,{path:p,bodyDir:bodies,sourceURI:'fixture:traktok-export'})).state).toBe('already_imported');
 expect(db.query('SELECT metadata_json FROM traktok_video_observation ORDER BY video_id LIMIT 1').get().metadata_json).toContain('café 🥣');
}));
test('100,000 synthetic records pass through bulk collection and native SourceFrontier, not a mock registry',()=>fixture(async({db,path,bodies,dir})=>{
 const p=join(dir,'scale.jsonl'),count=Number(process.env.BONFYRE_TRAKTOK_SCALE_ROWS??100000);expect(count).toBeGreaterThanOrEqual(10000);writeFileSync(p,'');
 for(let start=0;start<count;start+=1000)appendFileSync(p,Array.from({length:Math.min(1000,count-start)},(_,i)=>JSON.stringify(video(start+i))).join('\n')+'\n');
 const begin=performance.now(),r=await importExport(db,{path:p,bodyDir:bodies,sourceURI:'synthetic:scale-not-tiktok-network',maxRows:count,batchSize:1000});const ingestMs=performance.now()-begin;
 expect(r.rows).toBe(count);expect(status(db).unique_videos).toBe(count);expect(status(db).relations).toBe(count*3);
 const d=deliver(db,{dbPath:path,frontier,dir:join(dir,'out'),batchSize:5000});expect(d.delivered).toBe(1000);
 expect(db.query('SELECT count(*) n FROM channel').get().n).toBe(1000);expect(db.query("SELECT count(*) n FROM channel WHERE state<>'shadow'").get().n).toBe(0);
 console.log(JSON.stringify({witness:'synthetic_traktok_bulk',rows:count,ingest_ms:ingestMs,total_ms:performance.now()-begin,database_bytes:statSync(path).size,input_bytes:statSync(p).size,rss_bytes:process.memoryUsage().rss,network_requests:0}));
}),120000);

test('sealed Credentials owner authorizes the fixed collector without plaintext persistence',()=>fixture(async({db,bodies,dir,path})=>{
 const {credentialHeaders,API,FIELDS}=await import('../tools/traktok_collect.mjs');
 const binary=join(root,'cmd/BonfyreCredentials/bonfyre-credentials'),keyPath=join(dir,'key'),dbPath=join(dir,'credentials.db'),providersPath=join(dir,'providers.json');
 const secret='fixture-only-not-a-real-token',provider='fixture-research';
 writeFileSync(providersPath,JSON.stringify([{provider,name:'Fixture Research',purpose:'test',fields:[{field:'token',label:'Token',kind:'token',sensitive:true,required:true,generator:'',help:'fixture'}],apply:{headers:[{name:'Authorization',value:'Bearer {token}'}],query:[]},cannot_infer:'test is not a grant'}]));
 command(binary,['init-key','--key',keyPath]);
 const set=spawnSync(binary,['set','--db',dbPath,'--key',keyPath,'--providers',providersPath,'--provider',provider,'--field','token'],{input:secret,encoding:'utf8'});expect(set.status).toBe(0);
 const headersFor=credentialHeaders({binary,dbPath,keyPath,providersPath,provider});
 await expect(headersFor('https://other.example/')).rejects.toThrow('target');
 const {collection}=enqueue(db,query,'20260901','20260902');let requests=0;
 const r=await collect(db,{collection,bodyDir:bodies,token:'',headersFor,intervalMs:0,maxPages:1,transport:async(url,opt)=>{
  expect(url).toBe(API+'?fields='+FIELDS.join(','));expect(opt.headers.Authorization).toBe('Bearer '+secret);requests++;
  return new Response(page([{...video(1),effect_ids:['0']}],100,false));
 }});
 expect(r.state).toBe('complete');expect(requests).toBe(1);expect(status(db).relations).toBe(3);
 expect(readFileSync(dbPath).includes(Buffer.from(secret))).toBe(false);expect(readFileSync(path).includes(Buffer.from(secret))).toBe(false);
 const done=await collect(db,{collection,bodyDir:bodies,token:'',transport:async()=>{throw Error('must not refetch')}});expect(done.state).toBe('complete');expect(done.remote_requests).toBe(0);
}));
test('native SourceFrontier command dispatches the packaged collector and preserves failure codes',()=>fixture(async({path,dir})=>{
 const env={...process.env,BONFYRE_TRAKTOK_COLLECTOR:join(root,'cmd/BonfyreSourceFrontier/tools/traktok_collect.mjs'),BONFYRE_BUN_BINARY:process.execPath,TIKTOK_RESEARCH_ACCESS_TOKEN:''};
 const q=join(dir,'query.json');writeFileSync(q,JSON.stringify(query));
 const r=spawnSync(frontier,['traktok','run','--db',path,'--query',q,'--start','20260901','--end','20260930'],{encoding:'utf8',env});
 expect(r.status).toBe(2);const result=JSON.parse(r.stdout);expect(result.state).toBe('credentials_required');expect(result.remote_requests).toBe(0);
 const s=spawnSync(frontier,['traktok','status','--db',path],{encoding:'utf8',env});expect(s.status).toBe(0);expect(JSON.parse(s.stdout).collections).toBe(1);
}));

test('refresh generations preserve completed historical observations',()=>fixture(async({db,bodies})=>{
 const first=enqueue(db,query,'20260901','20260902'),shard=claim(db,first.collection);
 acceptPage(db,shard,page([video(1)],100,false),bodies);
 expect(enqueue(db,query,'20260901','20260902').collection).toBe(first.collection);
 expect(claim(db,first.collection)).toBe(null);
 const next=enqueue(db,query,'20260901','20260902','refresh:2026-10-04');expect(next.collection).not.toBe(first.collection);
 const work=claim(db,next.collection);expect(work.cursor).toBe('0');
 acceptPage(db,work,page([{...video(1),video_description:'Source correction'}],100,false),bodies);
 expect(status(db).unique_videos).toBe(1);expect(status(db).observations).toBe(2);
 expect(status(db).collections).toBe(2);
}));
test('a collected post re-enters the existing browser host with exact source bytes and no network',()=>fixture(async({db,path,bodies,dir})=>{
 const {readCapture}=await import('../tools/traktok_collect.mjs');
 const {createHost}=await import('../../../integrations/browser/host/bonfyre-browser-host.mjs');
 const {observe,cmsProjection,heldWorkEnvelope}=await import('../../../integrations/browser/extension/observation.mjs');
 const catalog=JSON.parse(readFileSync(join(root,'integrations/browser/extension/catalog.json'),'utf8'));
 const input=join(dir,'record.jsonl');writeFileSync(input,JSON.stringify({...video(8),voice_to_text:'Use the retained description, not invented preparation steps.',video_duration:null})+'\n');
 const {collection}=await importExport(db,{path:input,bodyDir:bodies,sourceURI:'fixture:source-export'});
 const before=createHash('sha256').update(readFileSync(path)).digest('hex');
 const host=createHost({env:{...process.env,BONFYRE_SOURCE_FRONTIER_DB:path,BONFYRE_SOURCE_FRONTIER_BINARY:frontier,BONFYRE_TRAKTOK_BODIES:bodies,BONFYRE_TRAKTOK_COLLECTOR:join(root,'cmd/BonfyreSourceFrontier/tools/traktok_collect.mjs'),BONFYRE_BUN_BINARY:process.execPath},tools:{call:()=>{throw Error('no network owner should be called')}}});
 const url='https://www.tiktok.com/@fixture_creator_8/video/'+video(8).id;
 const reply=await host.answer({operation:'collected',url,collection});expect(reply.ok).toBe(true);
 const c=reply.result.capture;expect(c.source_receipt.collection).toBe(collection);expect(c.structured[0].duration).toBeUndefined();
 const observation=await observe(c,catalog);expect(observation.offers).toHaveLength(0);expect(observation.recipes).toHaveLength(0);
 expect(observation.media[0].transcript).toContain('not invented preparation');
 expect(cmsProjection(observation).record.content).toContain(c.source_receipt.body_sha256);
 expect(JSON.parse(heldWorkEnvelope(observation,'Review this material').selection).source_receipt.collection).toBe(collection);
 expect(createHash('sha256').update(readFileSync(path)).digest('hex')).toBe(before);
 expect((await host.answer({operation:'collected',url:url.replace('creator_8','wrong'),collection})).ok).toBe(false);
 db.exec("UPDATE traktok_video_observation SET metadata_json='{}'");expect(()=>readCapture(db,{collection,video:video(8).id,bodyDir:bodies})).toThrow('differs');
 const body=db.query('SELECT body_path FROM traktok_page').get().body_path;writeFileSync(body,'damaged');
 expect(()=>readCapture(db,{collection,video:video(8).id,bodyDir:bodies})).toThrow('digest');
 expect((await host.answer({operation:'collected',url,collection})).ok).toBe(false);
}));
